import re
p='books/book-07-void-roads/CHAPTER_ARCHITECTURE.md'
s=open(p,encoding='utf-8').read()
MISSES=[]
def rep(old,new):
    global s
    n=s.count(old)
    if n!=1:
        MISSES.append(f"COUNT {n}: "+old[:100]); return
    s=s.replace(old,new)
def rep_chapter(num,title,newbody):
    global s
    m=re.search(r'\*\*Chapter %d — .*?\*\*\n~4,600 words\n\n(.*?)\n---\n'%num, s, re.S)
    assert m, f"chapter {num} not found"
    s=s[:m.start()]+f"**Chapter {num} — {title}**\n~4,600 words\n\n{newbody.rstrip()}\n\n---\n"+s[m.end():]
def close_swap(num, old_close, new_close):
    rep(old_close,new_close)

